import java.util.function.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Integer[] start = {1000, 2000, 3000};
        int limit = 2000;
        List<Integer> prices = List.of(start);
        // check 출력은 filter가 원소를 실제로 검사하는 순간을 보여 줘요.
